// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React, { useMemo } from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

const { fontFamily: interFamily } = loadInter();



export type TextAnimationProps = Record<string, any>;

const TextAnimation: React.FC<TextAnimationProps> = ({
  backgroundColor = "#080808",
  transparentBackground = false,
  durationInSeconds = 10,
  accentColor = "#4ade80",
  fontSize = 64,
  sentences = [
    { text: "It's treating taxes like a once a year chore", color: "#a3a3a3", isNewParagraph: true },
    { text: "instead of an ongoing strategy.", color: "#ffffff", isNewParagraph: false },
    { text: "Most successful professionals focus on growth.", color: "#4ade80", isNewParagraph: true }
  ]
}) => {
  const frame = useCurrentFrame();
  const { fps, width } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;
  const totalFrames = durationInSeconds * fps;

  // Group text into paragraphs and calculate stagger delays
  const paragraphs = useMemo(() => {
    const paras: Array<Array<{ word: string; delay: number; color: string }>> = [];
    let currentPara: Array<{ word: string; delay: number; color: string }> = [];
    let wordIndex = 0;

    sentences.forEach((block) => {
      if (block.isNewParagraph && currentPara.length > 0) {
        paras.push(currentPara);
        currentPara = [];
      }
      const words = block.text.split(/\s+/).filter((w) => w.length > 0);
      const processedWords = words.map((w) => {
        const delay = wordIndex * 3;
        wordIndex++;
        return { word: w, delay, color: block.color };
      });
      currentPara.push(...processedWords);
    });
    if (currentPara.length > 0) {
      paras.push(currentPara);
    }
    return paras;
  }, [sentences]);

  const lineSpring = spring({
    fps,
    frame: frame - 5,
    config: { damping: 20 },
  });
  const lineScaleY = interpolate(lineSpring, [0, 1], [0, 1]);

  const containerY = interpolate(
    spring({ fps, frame: frame - 5, config: { damping: 100, mass: 2 } }),
    [0, 1],
    [40, 0]
  );

  const globalOpacity = interpolate(
    frame,
    [totalFrames - 15, totalFrames],
    [1, 0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: interFamily }}>
      <div
        style={{
          opacity: globalOpacity,
          width: "100%",
          height: "100%",
          position: "relative",
        }}
      >
        {/* Ambient Glow */}
        <div
          style={{
            position: "absolute",
            top: "50%",
            left: "30%",
            width: "60vw",
            height: "60vw",
            backgroundColor: accentColor,
            filter: "blur(200px)",
            borderRadius: "50%",
            transform: "translate(-50%, -50%)",
            opacity: lineScaleY * 0.08,
            pointerEvents: "none",
          }}
        />

        {/* Text and Accent Layout */}
        <div
          style={{
            display: "flex",
            flexDirection: "row",
            width: width * 0.8,
            marginLeft: width * 0.1,
            position: "absolute",
            top: "50%",
            transform: `translateY(calc(-50% + ${containerY}px))`,
          }}
        >
          {/* Accent Line */}
          <div
            style={{
              width: "8px",
              backgroundColor: accentColor,
              marginRight: "4rem",
              transform: `scaleY(${lineScaleY})`,
              transformOrigin: "top",
              borderRadius: "4px",
              opacity: lineScaleY,
            }}
          />
          
          {/* Typographic Content */}
          <div
            style={{
              flex: 1,
              fontSize: `${fontSize}px`,
              fontWeight: 500,
              letterSpacing: "-0.02em",
              lineHeight: 1.35,
              display: "flex",
              flexDirection: "column",
            }}
          >
            {paragraphs.map((para, pIdx) => (
              <div
                key={pIdx}
                style={{ marginBottom: pIdx < paragraphs.length - 1 ? "1.5em" : 0 }}
              >
                {para.map((item, wIdx) => {
                  const wordSpring = spring({
                    fps,
                    frame: frame - item.delay - 10,
                    config: { damping: 14 },
                  });
                  const opacity = interpolate(
                    frame - item.delay - 10,
                    [0, 15],
                    [0, 1],
                    { extrapolateRight: "clamp", extrapolateLeft: "clamp" }
                  );
                  const y = interpolate(wordSpring, [0, 1], [30, 0]);
                  const blur = interpolate(
                    frame - item.delay - 10,
                    [0, 15],
                    [10, 0],
                    { extrapolateRight: "clamp", extrapolateLeft: "clamp" }
                  );

                  return (
                    <span
                      key={wIdx}
                      style={{
                        display: "inline-block",
                        opacity,
                        transform: `translateY(${y}px)`,
                        filter: blur > 0.01 ? `blur(${blur}px)` : "none",
                        color: item.color,
                        marginRight: "0.28em",
                        transition: "none",
                      }}
                    >
                      {item.word}
                    </span>
                  );
                })}
              </div>
            ))}
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default TextAnimation;